DELETE FROM `system_role`           WHERE `tenant_id` <> 1;
DELETE FROM `system_dept`           WHERE `tenant_id` <> 1;
DELETE FROM `system_notice`         WHERE `tenant_id` <> 1;
DELETE FROM `system_social_client`  WHERE `tenant_id` <> 1;
